<?php
namespace Tests\Feature;use App\Models\User;use Illuminate\Foundation\Testing\RefreshDatabase;use Tests\TestCase;
class CompanyQuotationTest extends TestCase{use RefreshDatabase;public function test_company_can_generate_versioned_quotation():void{$user=User::factory()->create(['account_type'=>'company']);$this->actingAs($user,'sanctum')->getJson('/api/v1/company/profile');$response=$this->actingAs($user,'sanctum')->postJson('/api/v1/company/quotations',['vacancies'=>3,'duration'=>30,'applications'=>'100','urgency'=>'urgent','visibility'=>'results','classification'=>'filters','diffusion'=>['platform','email'],'budget'=>10000]);$response->assertCreated()->assertJsonPath('data.currency','DOP')->assertJsonPath('meta.pricing_name','Tarifa inicial provisional')->assertJsonStructure(['data'=>['reference','answers','breakdown','subtotal','discount','tax','total','expires_at']]);$this->assertDatabaseCount('quotations',1);}public function test_viewer_cannot_create_quotation():void{$owner=User::factory()->create(['account_type'=>'company']);$viewer=User::factory()->create(['account_type'=>'company']);$companyId=$this->actingAs($owner,'sanctum')->getJson('/api/v1/company/profile')->json('data.id');$viewer->companies()->attach($companyId,['role'=>'viewer','status'=>'active']);$this->actingAs($viewer,'sanctum')->postJson('/api/v1/company/quotations',['vacancies'=>1,'duration'=>30,'applications'=>'50','urgency'=>'normal','visibility'=>'normal','classification'=>'manual','diffusion'=>[]])->assertForbidden();}}
